const body = $input.first()?.json?.body || $input.first()?.json || {};

// 2. Extract values and fall back to "tampines-wiki" if dropbox_root is missing
return [
  {
    "sessionId": body.sessionId,
    "action": "web",
    "chatInput": body.query,
    "dropbox_root": body.dropbox_root || "tampines-wiki"
  }
];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "output": {
      "description": "List of parsed and analyzed articles, OR an object wrapping that list under its own 'output' key (tolerates accidental double-nesting). Can be an empty array if no relevant articles were found.",
      "oneOf": [
        {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "articleId": {
                "type": "string",
                "description": "Unique NewsAPI article URI, copied exactly."
              },
              "relevant": {
                "type": "boolean",
                "description": "Relevance indicator."
              },
              "relevance_confidence": {
                "type": "number",
                "description": "Relevance confidence score, 0 to 1."
              },
              "relevance": {
                "type": "number",
                "description": "Deprecated alias sometimes used in place of relevance_confidence — treat as equivalent if present."
              },
              "relevance_reason": {
                "type": "string",
                "description": "Short reason for the classification."
              }
            },
            "required": ["articleId", "relevant"],
            "additionalProperties": false
          }
        },
        {
          "type": "object",
          "properties": {
            "output": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "articleId": { "type": "string" },
                  "relevant": { "type": "boolean" },
                  "relevance_confidence": { "type": "number" },
                  "relevance": { "type": "number" },
                  "relevance_reason": { "type": "string" }
                },
                "required": ["articleId", "relevant"],
                "additionalProperties": false
              }
            }
          },
          "required": ["output"],
          "additionalProperties": false
        }
      ]
    }
  },
  "required": ["output"],
  "additionalProperties": false
}

