// ============================================================
// 1. FETCH AI AGENT DATA SAFELY
// ============================================================

const aiAgentData = $('AI Agent').first().json || {};

const items =
  Array.isArray(aiAgentData.output)
    ? aiAgentData.output
    : [];

const intermediateSteps =
  Array.isArray(aiAgentData.intermediateSteps)
    ? aiAgentData.intermediateSteps
    : [];


// ============================================================
// 2. EXTRACT RAW NEWS SCRAPPER RESULTS
// ============================================================

const rawArticleMap = {};

intermediateSteps.forEach(step => {

  const toolName =
    (step.action && step.action.tool) || "";

  // Only process News Scrapper results
  if (
    toolName.toLowerCase() !== "news_scrapper"
  ) {
    return;
  }

  let obs = step.observation;

  // Observation may be returned as JSON string
  if (typeof obs === "string") {
    try {
      obs = JSON.parse(obs);
    } catch (error) {
      return;
    }
  }

  if (!obs) return;

  // Handle array wrapper
  const targetPayload =
    Array.isArray(obs)
      ? obs[0]
      : obs;

  if (!targetPayload) return;

  let results = [];

  // Standard NewsAPI.ai structure
  if (
    targetPayload.articles &&
    Array.isArray(
      targetPayload.articles.results
    )
  ) {

    results =
      targetPayload.articles.results;

  // Alternative results structure
  } else if (
    Array.isArray(targetPayload.results)
  ) {

    results =
      targetPayload.results;

  // Direct array
  } else if (
    Array.isArray(targetPayload)
  ) {

    results =
      targetPayload;
  }


  // Store articles using their URI
  results.forEach(article => {

    if (
      !article ||
      typeof article !== "object"
    ) {
      return;
    }

    const id =
      article.uri ||
      article.id ||
      article.articleId;

    if (!id) return;

    rawArticleMap[String(id)] =
      article;
  });

});


// ============================================================
// 3. OUTPUT ARRAYS
// ============================================================

const outputItems = [];

const quarantineItems = [];


// ============================================================
// 4. PROCESS AI CLASSIFICATIONS
// ============================================================

items.forEach(c => {

  if (
    !c ||
    !c.articleId
  ) {
    return;
  }

  const articleId =
    String(c.articleId);


  // ==========================================================
  // 5. FIND MATCHING RAW NEWS SCRAPPER ARTICLE
  // ==========================================================

  const raw =
    rawArticleMap[articleId];


  // ==========================================================
  // 6. EMPTY-SHELL DETECTION
  //
  // If AI Agent returned an articleId but the matching
  // News Scrapper article doesn't exist, quarantine it.
  // ==========================================================

  if (
    !raw ||
    typeof raw !== "object" ||
    Object.keys(raw).length === 0
  ) {

    quarantineItems.push({

      articleId:
        articleId,

      dataType:
        c.dataType || "news",

      relevant:
        c.relevant ?? false,

      relevance_confidence:
        c.relevance_confidence ?? 0,

      relevance_reason:
        c.relevance_reason || "",

      articleDataStatus:
        "quarantined_missing_scraper_data",

      quarantineReason:
        "AI classification exists but matching raw News Scrapper article was not found."

    });

    return;
  }


  // ==========================================================
  // 7. SOURCE INFORMATION
  // ==========================================================

  const source =
    raw.source || {};

  const sourceLocation =
    source.location || {};



  // ==========================================================
  // 8. PUBLISHER LOCATION
  //
  // This is ONLY the location provided by the API.
  //
  // Example:
  // "Kuala Lumpur"
  // "Malaysia"
  // "London"
  //
  // We do NOT use this value to determine country.
  // ==========================================================

  const publisherLocation =
    sourceLocation?.label?.eng || "";



  // ==========================================================
  // 9. PUBLISHER COUNTRY
  //
  // IMPORTANT:
  //
  // ONLY take the country from the API's nested
  // location.country object.
  //
  // NEVER do:
  //
  // publisherCountry = publisherLocation
  //
  // Even when:
  //
  // location.type = "country"
  //
  // If the API does not provide:
  //
  // source.location.country.label.eng
  //
  // publisherCountry remains EMPTY.
  // ==========================================================

  const publisherCountry =
    sourceLocation?.country?.label?.eng || "";



  // ==========================================================
  // 10. PUBLISHER LOCATION VALIDATED
  //
  // Keep the API's validation flag as a separate field.
  // ==========================================================

  const publisherLocationValidated =
    source?.locationValidated ?? false;



  // ==========================================================
  // 11. PUBLISHER TYPE / CATEGORY
  //
  // Capture only values actually returned by the API.
  // Do not invent mainstream/trade/wire/broadcast.
  // ==========================================================

  const publisherType =
    source?.type ||
    source?.sourceType ||
    source?.mediaType ||
    source?.category ||
    "";

  const publisherGroup =
    source?.group ||
    source?.groupUri ||
    "";



  // ==========================================================
  // 12. STANDARDIZED ARTICLE OBJECT
  // ==========================================================

  const article = {

    articleId:
      articleId,

    articleTitle:
      raw.title || "",

    url:
      raw.url || "",

    language:
      raw.lang || "",

    author:
      (
        raw.authors &&
        raw.authors[0] &&
        raw.authors[0].name
      ) || "",

    dataType:
      raw.dataType || "news",

    publishedDate:
      raw.dateTimePub ||
      raw.dateTime ||
      raw.date ||
      "",

    publisherName:
      source.title || "",

    publisherDomain:
      source.uri || "",


    // --------------------------------------------------------
    // Publisher Location
    // --------------------------------------------------------

    publisherLocation:
      publisherLocation,


    // --------------------------------------------------------
    // Publisher Country
    //
    // ONLY from:
    // source.location.country.label.eng
    // --------------------------------------------------------

    publisherCountry:
      publisherCountry,


    // --------------------------------------------------------
    // API validation status
    // --------------------------------------------------------

    publisherLocationValidated:
      publisherLocationValidated,


    // --------------------------------------------------------
    // Publisher type/category if available
    // --------------------------------------------------------

    publisherType:
      publisherType,

    publisherGroup:
      publisherGroup,


    // --------------------------------------------------------
    // Other article metadata
    // --------------------------------------------------------

    concepts:
      raw.concepts || [],

    categories:
      raw.categories || [],

    articleLocation:
      raw.location
        ? String(raw.location)
        : "null",

    duplicateList:
      raw.duplicateList || [],

    duplicateFlag:
      String(
        raw.isDuplicate ?? false
      ),

    originalArticleReference:
      raw.originalArticle
        ? String(raw.originalArticle)
        : "null",

    rawNewsApiResponse:
      raw,

    body:
      raw.body || "",


    // --------------------------------------------------------
    // AI relevance classification
    // --------------------------------------------------------

    relevant:
      c.relevant !== undefined
        ? c.relevant
        : false,

    relevance_confidence:
      c.relevance_confidence !== undefined
        ? c.relevance_confidence
        : 0,

    relevance_reason:
      c.relevance_reason || "",


    // --------------------------------------------------------
    // Article data status
    // --------------------------------------------------------

    articleDataStatus:
      "complete"
  };



  // ==========================================================
  // 13. CREATE FRONTMATTER
  // ==========================================================

  const frontmatterFields = {
    ...article
  };


  // Body is added separately
  delete frontmatterFields.body;


  // Raw response is added separately
  delete frontmatterFields.rawNewsApiResponse;


  let frontmatter =
    "---\n";


  for (
    const [key, value]
    of Object.entries(frontmatterFields)
  ) {

    let safeValue;


    if (
      value !== null &&
      typeof value === "object"
    ) {

      safeValue =
        JSON.stringify(value)
          .replace(
            /'/g,
            "''"
          );

    } else {

      safeValue =
        String(value ?? "")
          .replace(
            /'/g,
            "''"
          );
    }


    frontmatter +=
      `${key}: '${safeValue}'\n`;
  }



  // ==========================================================
  // 14. ADD RAW NEWSAPI.AI RESPONSE
  // ==========================================================

  const safeRawResponse =
    JSON.stringify(
      article.rawNewsApiResponse || {}
    )
      .replace(
        /'/g,
        "''"
      );


  frontmatter +=
    `rawNewsApiResponse: '${safeRawResponse}'\n`;

  frontmatter +=
    "---\n\n";



  // ==========================================================
  // 15. FINAL MARKDOWN CONTENT
  // ==========================================================

  const finalMarkdownFile =
    frontmatter +
    article.body;



  // ==========================================================
  // 16. SAFE FILE NAME
  // ==========================================================

  const cleanId =
    String(article.articleId)
      .replace(
        /[^a-zA-Z0-9]/g,
        "_"
      );


  const cleanSlug =
    (
      article.articleTitle ||
      "untitled"
    )
      .toLowerCase()
      .replace(
        /[^a-z0-9]/g,
        "-"
      )
      .replace(
        /-+/g,
        "-"
      )
      .replace(
        /^-|-$/g,
        ""
      )
      .slice(
        0,
        50
      )
      .replace(
        /-$/,
        ""
      );


  const fileName =
    `${cleanId}-${cleanSlug}.md`
      .trim();



  // ==========================================================
  // 17. PUSH FINAL ARTICLE
  // ==========================================================

  outputItems.push({

    json: {
      fileName,
      ...article
    },

    binary: {

      data: {

        data:
          Buffer
            .from(
              finalMarkdownFile,
              "utf-8"
            )
            .toString("base64"),

        mimeType:
          "text/markdown",

        fileName:
          fileName
      }
    }
  });

});


// ============================================================
// 18. RETURN NORMAL ARTICLES
//
// Empty-shell articles are NOT returned to the normal pipeline.
// ============================================================

return outputItems;

const sessionId = $('DATA').first().json.sessionId;

return [
  {
    json: {
      sessionId,
      status: "completed",
      articleCount: $('Response').all().length,
      error: null
    }
  }
];
